IF FirstScan THEN
    Fv_3_3040_Out   := 6554;
    Fv_3_3041_Out   := 6554;
    XV_ISA_001      := FALSE;
    XV_ISA_002      := FALSE;
    FIC_10_Integral := 0.0;
    FIC_11_Integral := 0.0;
    (* Ensure latches start in known de-energised state *)
    FT_10_HH_Latch(S1 := FALSE, R := TRUE);
    FT_10_LL_Latch(S1 := FALSE, R := TRUE);
    FT_11_HH_Latch(S1 := FALSE, R := TRUE);
    FT_11_LL_Latch(S1 := FALSE, R := TRUE);
    FirstScan       := FALSE;
    RETURN;
END_IF;

FT_10_Scaled := ((INT_TO_REAL(FT_10_Raw) - 6554.0) / (32767.0 - 6554.0)) * FT_10_EU_Span + FT_10_EU_Min;
FT_11_Scaled := ((INT_TO_REAL(FT_11_Raw) - 6554.0) / (32767.0 - 6554.0)) * FT_11_EU_Span + FT_11_EU_Min;

IF FT_10_Scaled >= FT_10_HH_SP THEN
    FT_10_HH := TRUE;
ELSIF FT_10_Scaled <= (FT_10_HH_SP - FT_10_Deadband) THEN
    FT_10_HH := FALSE;
END_IF;

IF FT_10_Scaled >= FT_10_H_SP THEN
    FT_10_H := TRUE;
ELSIF FT_10_Scaled <= (FT_10_H_SP - FT_10_Deadband) THEN
    FT_10_H := FALSE;
END_IF;

IF FT_10_Scaled <= FT_10_L_SP THEN
    FT_10_L := TRUE;
ELSIF FT_10_Scaled >= (FT_10_L_SP + FT_10_Deadband) THEN
    FT_10_L := FALSE;
END_IF;

IF FT_10_Scaled <= FT_10_LL_SP THEN
    FT_10_LL := TRUE;
ELSIF FT_10_Scaled >= (FT_10_LL_SP + FT_10_Deadband) THEN
    FT_10_LL := FALSE;
END_IF;

FT_10_HH_Latch(S1 := FT_10_HH,
               R  := (FT_10_HH_Ack AND NOT FT_10_HH));

FT_10_LL_Latch(S1 := FT_10_LL,
               R  := (FT_10_LL_Ack AND NOT FT_10_LL));

IF FT_11_Scaled >= FT_11_HH_SP THEN
    FT_11_HH := TRUE;
ELSIF FT_11_Scaled <= (FT_11_HH_SP - FT_11_Deadband) THEN
    FT_11_HH := FALSE;
END_IF;

IF FT_11_Scaled >= FT_11_H_SP THEN
    FT_11_H := TRUE;
ELSIF FT_11_Scaled <= (FT_11_H_SP - FT_11_Deadband) THEN
    FT_11_H := FALSE;
END_IF;

IF FT_11_Scaled <= FT_11_L_SP THEN
    FT_11_L := TRUE;
ELSIF FT_11_Scaled >= (FT_11_L_SP + FT_11_Deadband) THEN
    FT_11_L := FALSE;
END_IF;

IF FT_11_Scaled <= FT_11_LL_SP THEN
    FT_11_LL := TRUE;
ELSIF FT_11_Scaled >= (FT_11_LL_SP + FT_11_Deadband) THEN
    FT_11_LL := FALSE;
END_IF;

FT_11_HH_Latch(S1 := FT_11_HH,
               R  := (FT_11_HH_Ack AND NOT FT_11_HH));

FT_11_LL_Latch(S1 := FT_11_LL,
               R  := (FT_11_LL_Ack AND NOT FT_11_LL));

FIC_10_Error    := FT_10_SP - FT_10_Scaled;
FIC_10_Integral := FIC_10_Integral + (FIC_10_Ki * FIC_10_Error);
IF FIC_10_Integral > 100.0 THEN
    FIC_10_Integral := 100.0;
ELSIF FIC_10_Integral < 0.0 THEN
    FIC_10_Integral := 0.0;
END_IF;
FIC_10_Output := (FIC_10_Kp * FIC_10_Error) + FIC_10_Integral;
IF FIC_10_Output > 100.0 THEN
    FIC_10_Output := 100.0;
ELSIF FIC_10_Output < 0.0 THEN
    FIC_10_Output := 0.0;
END_IF;
Fv_3_3040_Out := REAL_TO_INT(6554.0 + (FIC_10_Output / 100.0) * (32767.0 - 6554.0));

FIC_11_Error    := FT_11_SP - FT_11_Scaled;
FIC_11_Integral := FIC_11_Integral + (FIC_11_Ki * FIC_11_Error);
IF FIC_11_Integral > 100.0 THEN
    FIC_11_Integral := 100.0;
ELSIF FIC_11_Integral < 0.0 THEN
    FIC_11_Integral := 0.0;
END_IF;
FIC_11_Output := (FIC_11_Kp * FIC_11_Error) + FIC_11_Integral;
IF FIC_11_Output > 100.0 THEN
    FIC_11_Output := 100.0;
ELSIF FIC_11_Output < 0.0 THEN
    FIC_11_Output := 0.0;
END_IF;
Fv_3_3041_Out := REAL_TO_INT(6554.0 + (FIC_11_Output / 100.0) * (32767.0 - 6554.0));

(* Instrument air isolation valves — open when no HH or LL alarm latched *)
XV_ISA_001_Cmd := NOT (FT_10_HH_Latch.Q1 OR FT_10_LL_Latch.Q1 OR FT_11_HH_Latch.Q1 OR FT_11_LL_Latch.Q1);
XV_ISA_002_Cmd := XV_ISA_001_Cmd;
XV_ISA_001     := XV_ISA_001_Cmd;
XV_ISA_002     := XV_ISA_002_Cmd;

System_Alarm :=
    FT_10_HH_Latch.Q1 OR FT_10_LL_Latch.Q1 OR
    FT_10_H            OR FT_10_L            OR
    FT_11_HH_Latch.Q1 OR FT_11_LL_Latch.Q1 OR
    FT_11_H            OR FT_11_L;
